1	/* ============================================================
2	   tierlist.js — 英雄梯度排行榜核心引擎
3	   支持 LOLM（分路/Z-score） 和 曙光英雄（无分路/加权和）
4	   ============================================================ */
5	
6	"use strict";
7	
8	// ---- 全局状态 ----
9	let gameConfig = null;      // 当前游戏的 config.json
10	let gameData = null;        // 计算后的结构化数据
11	let currentMethod = "zscore"; // LOLM: "zscore"|"simple", SG: "weighted"
12	let currentView = "lane";   // "lane"|"global"
13	let currentLane = null;     // 当前分路名（仅 hasLanes）
14	let currentViewMode = "table"; // "table"|"grid" — 展示模式
15	let currentDate = null;      // 当前选中的日期 (YYYY-MM-DD)，仅 hasDates 游戏
16	
17	// ---- 工具函数 ----
18	function parsePct(s) {
19	  if (typeof s === "number") return s / 100;
20	  return parseFloat(String(s).replace("%", "")) / 100;
21	}
22	
23	function mean(arr) {
24	  return arr.reduce((a, b) => a + b, 0) / arr.length;
25	}
26	
27	function stdDev(arr) {
28	  const m = mean(arr);
29	  const v = arr.reduce((s, v) => s + (v - m) ** 2, 0) / arr.length;
30	  return Math.sqrt(v) || 1;
31	}
32	
33	function zScores(arr) {
34	  const m = mean(arr);
35	  const s = stdDev(arr);
36	  if (s === 0) return arr.map(() => 0);
37	  return arr.map(v => (v - m) / s);
38	}
39	
40	function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }
41	
42	function getRankClass(rank) {
43	  if (rank === 1) return "rank-1";
44	  if (rank === 2) return "rank-2";
45	  if (rank === 3) return "rank-3";
46	  return "";
47	}
48	
49	function getWrClass(val) {
50	  if (val >= 0.52) return "wr-high";
51	  if (val >= 0.49) return "wr-mid";
52	  return "wr-low";
53	}
54	
55	function getCwClass(val) {
56	  // 战力分：高(>140) 中(80-140) 低(<80)
57	  if (val >= 140) return "cw-high";
58	  if (val >= 80) return "cw-mid";
59	  return "cw-low";
60	}
61	
62	// ---- 梯度系统 ----
63	function getTierColors() {
64	  return gameConfig.tiers.colors;
65	}
66	
67	function getTierThresholds() {
68	  return gameConfig.tiers.thresholds;
69	}
70	
71	function getTierBadge(tier) {
72	  const color = getTierColors()[tier] || "#8c8c8c";
73	  return `<span class="tier-badge" style="background:${color}">${tier}</span>`;
74	}
75	
76	function getScoreBar(score, tier) {
77	  const color = getTierColors()[tier] || "#8c8c8c";
78	  return `<div class="score-bar-wrap">
79	    <div class="score-bar"><div class="score-bar-fill" style="width:${score}%;background:${color}"></div></div>
80	    <span class="score-value">${score.toFixed(1)}</span></div>`;
81	}
82	
83	function assignTiers(heroes, scoreKey) {
84	  const sorted = [...heroes].sort((a, b) => b[scoreKey] - a[scoreKey]);
85	  const n = sorted.length;
86	  const thresholds = getTierThresholds();
87	  sorted.forEach((h, rank) => {
88	    const pct = 1 - rank / n;
89	    let tier = "T4";
90	    for (const t of thresholds) {
91	      if (pct >= t.pct) { tier = t.tier; break; }
92	    }
93	    h.tier = tier;
94	    h.rank = rank + 1;
95	  });
96	}
97	
98	// ============================================================
99	// LOLM 算法
100	// ============================================================
101	function computeLOLM(rawData) {
102	  const hasLanes = gameConfig.hasLanes;
103	  const lanes = {};
104	  const allHeroes = [];
105	
106	  for (const laneCfg of gameConfig.lanes) {
107	    const raw = rawData[laneCfg.name];
108	    if (!raw) continue;
109	    const heroes = raw.map(h => ({
110	      name: h.heroName,
111	      lane: laneCfg.name,
112	      headIcon: gameConfig.headIconPath ? (gameConfig.gameId + "/" + gameConfig.headIconPath.replace("{name}", h.heroName)) : null,
113	      wr: parsePct(h.winRate),
114	      pr: parsePct(h.pickRate),
115	      br: parsePct(h.banRate),
116	      bp: parsePct(h.pickRate) + parsePct(h.banRate)
117	    }));
118	    lanes[laneCfg.name] = heroes;
119	    allHeroes.push(...heroes);
120	  }
121	
122	  // Z-score 加权（分路内计算 Z-score）
123	  for (const [laneName, heroes] of Object.entries(lanes)) {
124	    const zWr = zScores(heroes.map(h => h.wr));
125	    const zPr = zScores(heroes.map(h => h.pr));
126	    const zBr = zScores(heroes.map(h => h.br));
127	    heroes.forEach((h, i) => {
128	      h.z_wr = zWr[i]; h.z_pr = zPr[i]; h.z_br = zBr[i];
129	      h.raw_zscore = 0.5 * zWr[i] + 1.0 * zPr[i] + 3.0 * zBr[i];
130	    });
131	  }
132	
133	  // 简易公式
134	  for (const [laneName, heroes] of Object.entries(lanes)) {
135	    heroes.forEach(h => {
136	      h.raw_simple = Math.pow(h.wr, 0.3) * (h.pr + 2.5 * h.br) * 100;
137	    });
138	  }
139	
140	  // 分路内 min-max 归一化
141	  function normalize(heroes, rawKey, normKey) {
142	    const vals = heroes.map(h => h[rawKey]);
143	    const lo = Math.min(...vals), hi = Math.max(...vals);
144	    const rng = hi - lo || 1;
145	    heroes.forEach(h => { h[normKey] = ((h[rawKey] - lo) / rng) * 100; });
146	  }
147	
148	  for (const [, heroes] of Object.entries(lanes)) {
149	    normalize(heroes, "raw_zscore", "score_zscore");
150	    normalize(heroes, "raw_simple", "score_simple");
151	  }
152	
153	  // 全局归一化
154	  normalize(allHeroes, "raw_zscore", "score_zscore_global");
155	  normalize(allHeroes, "raw_simple", "score_simple_global");
156	
157	  // 分配梯度
158	  for (const [, heroes] of Object.entries(lanes)) {
159	    assignTiersWithKey(heroes, "score_zscore", "tier_zscore");
160	    assignTiersWithKey(heroes, "score_simple", "tier_simple");
161	    assignTiersWithKey(heroes, "score_zscore_global", "tier_global");
162	  }
163	
164	  function assignTiersWithKey(heroes, scoreKey, tierKey) {
165	    const sorted = [...heroes].sort((a, b) => b[scoreKey] - a[scoreKey]);
166	    const n = sorted.length;
167	    const thresholds = getTierThresholds();
168	    sorted.forEach((h, i) => {
169	      const pct = 1 - i / n;
170	      let tier = "T4";
171	      for (const t of thresholds) {
172	        if (pct >= t.pct) { tier = t.tier; break; }
173	      }
174	      h[tierKey] = tier;
175	      // Store lane rank under a consistent key: _rank_zscore / _rank_simple
176	      if (tierKey === "tier_zscore") h._rank_zscore = i + 1;
177	      if (tierKey === "tier_simple") h._rank_simple = i + 1;
178	    });
179	  }
180	
181	  // 全局排名
182	  const globalZ = [...allHeroes].sort((a, b) => b.score_zscore_global - a.score_zscore_global);
183	  globalZ.forEach((h, i) => { h.global_rank_zscore = i + 1; });
184	  const globalSimple = [...allHeroes].sort((a, b) => b.score_simple_global - a.score_simple_global);
185	  globalSimple.forEach((h, i) => { h.global_rank_simple = i + 1; });
186	
187	  return { lanes, allHeroes, globalZ, globalSimple };
188	}
189	
190	// ============================================================
191	// 曙光英雄算法（从 Python validate_pure.py 移植）
192	// ============================================================
193	function computeSG(rawData) {
194	  const heroes = rawData.map(h => ({
195	    name: h.heroName,
196	    headIcon: gameConfig.headIconPath ? ("曙光英雄/" + gameConfig.headIconPath.replace("{name}", h.heroName)) : null,
197	    appearanceRank: parseInt(h.appearanceRank),
198	    combatPower: parseFloat(h.combatPower),
199	    winRate: parseFloat(String(h.winRate).replace("%", "")) / 100,
200	    lane: null
201	  }));
202	
203	  const N = heroes.length;
204	  const weights = gameConfig.algorithm.weights;
205	
206	  // 出场分：rank 越小越好，转换为 1 → 1.0, N → 0.0
207	  const appearanceScores = heroes.map(h => 1 - (h.appearanceRank - 1) / (N - 1));
208	
209	  // 战力分 min-max 归一化
210	  const combatVals = heroes.map(h => h.combatPower);
211	  const combatMin = Math.min(...combatVals), combatMax = Math.max(...combatVals);
212	  const combatRange = combatMax - combatMin || 1;
213	  const combatScores = combatVals.map(v => (v - combatMin) / combatRange);
214	
215	  // 胜率 min-max 归一化
216	  const wrVals = heroes.map(h => h.winRate);
217	  const wrMin = Math.min(...wrVals), wrMax = Math.max(...wrVals);
218	  const wrRange = wrMax - wrMin || 1;
219	  const wrScores = wrVals.map(v => (v - wrMin) / wrRange);
220	
221	  // 加权和
222	  heroes.forEach((h, i) => {
223	    h.raw_weighted = weights.appearance * appearanceScores[i]
224	                   + weights.combat * combatScores[i]
225	                   + weights.winrate * wrScores[i];
226	  });
227	
228	  // 最终 min-max 归一化 → 0~100
229	  const rawVals = heroes.map(h => h.raw_weighted);
230	  const rawMin = Math.min(...rawVals), rawMax = Math.max(...rawVals);
231	  const rawRange = rawMax - rawMin || 1;
232	  heroes.forEach(h => { h.score = ((h.raw_weighted - rawMin) / rawRange) * 100; });
233	
234	  // 分配梯度
235	  const sorted = [...heroes].sort((a, b) => b.score - a.score);
236	  const thresholds = getTierThresholds();
237	  sorted.forEach((h, i) => {
238	    const pct = 1 - i / N;
239	    let tier = "T4";
240	    for (const t of thresholds) {
241	      if (pct >= t.pct) { tier = t.tier; break; }
242	    }
243	    h.tier = tier;
244	    h.rank = i + 1;
245	  });
246	
247	  return { heroes, sorted };
248	}
249	
250	// ============================================================
251	// 数据加载 + 计算调度
252	// ============================================================
253	async function loadGameData() {
254	  const base = gameConfig.gameId === "lolm" ? "lolm" : "曙光英雄";
255	
256	  if (gameConfig.hasLanes) {
257	    // LOLM: 加载所有分路 JSON
258	    const results = await Promise.all(
259	      gameConfig.lanes.map(async lane => {
260	        const resp = await fetch(base + "/" + lane.dataFile);
261	        if (!resp.ok) throw new Error(`加载 ${lane.dataFile} 失败: ${resp.status}`);
262	        return [lane.name, await resp.json()];
263	      })
264	    );
265	    const rawData = Object.fromEntries(results);
266	    const data = computeLOLM(rawData);
267	
268	    // 转换为标准格式
269	    gameData = {
270	      hasLanes: true,
271	      lanes: {},
272	      allHeroes: data.allHeroes,
273	      globalZ: data.globalZ,
274	      globalSimple: data.globalSimple
275	    };
276	    for (const [name, heroes] of Object.entries(data.lanes)) {
277	      gameData.lanes[name] = heroes;
278	    }
279	  } else {
280	    // 无分路模式：支持多日期或单文件
281	    let dataFile;
282	    if (gameConfig.hasDates && gameConfig.dates && gameConfig.dates.length > 0) {
283	      const dateEntry = gameConfig.dates.find(d => d.date === currentDate) || gameConfig.dates[0];
284	      dataFile = dateEntry.file;
285	      if (!currentDate) currentDate = dateEntry.date;
286	    } else {
287	      dataFile = gameConfig.dataFile;
288	    }
289	    const resp = await fetch(base + "/" + dataFile);
290	    if (!resp.ok) throw new Error(`加载数据失败: ${resp.status}`);
291	    const rawData = await resp.json();
292	    const data = computeSG(rawData);
293	    gameData = {
294	      hasLanes: false,
295	      heroes: data.heroes,
296	      sorted: data.sorted
297	    };
298	
299	    // 如果有历史数据，加载上一期数据用于梯度变化对比
300	    if (gameConfig.hasDates && gameConfig.dates && gameConfig.dates.length >= 2) {
301	      const sortedDates = gameConfig.dates.map(d => d.date).sort();
302	      const curIdx = sortedDates.indexOf(currentDate);
303	      if (curIdx > 0) {
304	        const prevDate = sortedDates[curIdx - 1];
305	        const prevEntry = gameConfig.dates.find(d => d.date === prevDate);
306	        if (prevEntry) {
307	          try {
308	            const prevResp = await fetch(base + "/" + prevEntry.file);
309	            if (prevResp.ok) {
310	              const prevRaw = await prevResp.json();
311	              const prevResult = computeSG(prevRaw);
312	              const prevMap = new Map(prevResult.heroes.map(h => [h.name, h]));
313	              data.heroes.forEach(h => {
314	                const prev = prevMap.get(h.name);
315	                if (prev) {
316	                  h.prevTier = prev.tier;
317	                  h.prevScore = prev.score;
318	                  h.prevRank = prev.rank;
319	                }
320	              });
321	            }
322	          } catch (e) { /* 静默失败，不影响当前数据展示 */ }
323	        }
324	      }
325	    }
326	  }
327	}
328	
329	// ============================================================
330	// 获取当前有效的字段
331	// ============================================================
332	function getScoreField(hero) {
333	  if (gameConfig.hasLanes) {
334	    return currentMethod === "zscore" ? "score_zscore" : "score_simple";
335	  }
336	  return "score";
337	}
338	
339	function getTierField(hero) {
340	  if (gameConfig.hasLanes) {
341	    return currentMethod === "zscore" ? "tier_zscore" : "tier_simple";
342	  }
343	  return "tier";
344	}
345	
346	function getGlobalRank(hero) {
347	  if (gameConfig.hasLanes) {
348	    return hero[currentMethod === "zscore" ? "global_rank_zscore" : "global_rank_simple"];
349	  }
350	  return hero.rank;
351	}
352	
353	// ============================================================
354	// 渲染
355	// ============================================================
356	function formatCellValue(hero, col) {
357	  const val = hero[col.field];
358	  if (val == null) return "-";
359	
360	  switch (col.type) {
361	    case "rank":
362	      return `<span class="rank-num ${getRankClass(val)}">${val}</span>`;
363	    case "tier":
364	      return getTierBadge(val);
365	    case "score":
366	      return getScoreBar(val, hero.tier || hero[getTierField(hero)] || "T4");
367	    case "pct": {
368	      const pctVal = val * 100;
369	      let cls = "";
370	      if (col.colorClass === "wr") cls = getWrClass(val);
371	      if (col.colorClass === "cw") cls = getCwClass(val);
372	      return cls ? `<span class="${cls}">${pctVal.toFixed(2)}%</span>` : `${pctVal.toFixed(2)}%`;
373	    }
374	    case "int":
375	      return val.toString();
376	    default:
377	      return String(val);
378	  }
379	}
380	
381	function getSortValue(hero, col) {
382	  const val = hero[col.field];
383	  if (val == null) return 0;
384	  if (col.type === "tier") {
385	    const order = ["T0", "T0.5", "T1", "T2", "T3", "T4"];
386	    return order.indexOf(val);
387	  }
388	  if (typeof val === "number") return val;
389	  return String(val);
390	}
391	
392	function renderTable(heroes, columns, highlightLane) {
393	  // highlightLane: if set, highlight heroes from that lane
394	  let html = '<div class="table-wrapper"><table><thead><tr>';
395	  columns.forEach((col, idx) => {
396	    html += `<th onclick="sortTable(this, ${idx})" data-col-idx="${idx}">
397	      ${col.label} <span class="sort-icon">↕</span></th>`;
398	  });
399	  html += '</tr></thead><tbody>';
400	
401	  heroes.forEach(h => {
402	    let rowClass = "";
403	    if (highlightLane && h.lane === highlightLane) rowClass = ' class="current-highlight"';
404	    html += `<tr${rowClass}>`;
405	    columns.forEach(col => {
406	      // Resolve field value — some are computed
407	      let displayVal;
408	      if (col.field === "score") {
409	        displayVal = h[getScoreField(h)];
410	      } else if (col.field === "scoreGlobal") {
411	        displayVal = h[gameConfig.hasLanes ? (currentMethod === "zscore" ? "score_zscore_global" : "score_simple_global") : "score"];
412	      } else if (col.field === "tier") {
413	        displayVal = gameConfig.hasLanes ? h[getTierField(h)] : h.tier;
414	      } else if (col.field === "globalRank") {
415	        displayVal = getGlobalRank(h);
416	      } else {
417	        displayVal = h[col.field];
418	      }
419	
420	      // Format
421	      if (col.type === "rank") {
422	        html += `<td class="rank-num ${getRankClass(displayVal)}">${displayVal}</td>`;
423	      } else if (col.type === "tier") {
424	        let badge = getTierBadge(displayVal);
425	        // 显示与上一期的梯度变化箭头（仅无分路游戏 + 有 prevTier 数据）
426	        if (!gameConfig.hasLanes && h.prevTier && h.prevTier !== displayVal) {
427	          const tierOrder = ["T4","T3","T2","T1","T0.5","T0"];
428	          const arrow = tierOrder.indexOf(displayVal) > tierOrder.indexOf(h.prevTier)
429	            ? ' <span style="color:#3fb950;font-size:0.7rem">▲</span>'
430	            : ' <span style="color:#f85149;font-size:0.7rem">▼</span>';
431	          badge += arrow;
432	        }
433	        html += `<td>${badge}</td>`;
434	      } else if (col.type === "score") {
435	        html += `<td>${getScoreBar(displayVal, h.tier || displayVal)}</td>`;
436	      } else if (col.type === "pct" && displayVal != null) {
437	        const pctVal = displayVal * 100;
438	        let cls = "";
439	        if (col.colorClass === "wr") cls = getWrClass(displayVal);
440	        if (col.colorClass === "cw") cls = getCwClass(displayVal);
441	        html += `<td class="${cls}">${pctVal.toFixed(2)}%</td>`;
442	      } else if (col.type === "int" && displayVal != null) {
443	        let cls = "";
444	        if (col.colorClass === "cw") cls = getCwClass(displayVal);
445	        html += `<td class="${cls}">${displayVal}</td>`;
446	      } else {
447	        let txt = displayVal != null ? displayVal : "-";
448	        // Render head icon + name for text columns when hero has an icon
449	        if (col.type === "text" && col.field === "name" && h.headIcon) {
450	          const clickable = !gameConfig.hasLanes && gameConfig.hasDates ? ` style="cursor:pointer" onclick="showHeroDetail('${h.name.replace(/'/g, "\\'")}')"` : '';
451	          txt = `<div class="hero-cell"${clickable}><img class="hero-icon" src="${h.headIcon}" alt="${h.name}" onerror="this.style.display='none'"> <span class="hero-name">${txt}</span></div>`;
452	        } else if (col.type === "text" && col.field === "name") {
453	          const clickable = !gameConfig.hasLanes && gameConfig.hasDates ? ` style="cursor:pointer" onclick="showHeroDetail('${h.name.replace(/'/g, "\\'")}')"` : '';
454	          txt = `<span class="hero-name"${clickable}>${txt}</span>`;
455	        }
456	        html += `<td>${txt}</td>`;
457	      }
458	    });
459	    html += '</tr>';
460	  });
461	
462	  html += '</tbody></table></div>';
463	  return html;
464	}
465	
466	function renderGridView(heroes, highlightLane) {
467	  // 按梯度分组
468	  const tierOrder = ["T0", "T0.5", "T1", "T2", "T3", "T4"];
469	  const validTiers = new Set(tierOrder);
470	  const colors = getTierColors();
471	  const groups = {};
472	  tierOrder.forEach(t => { groups[t] = []; });
473	
474	  // 兜底组：收集无法解析梯度的英雄（避免污染 T4）
475	  const unknownGroup = [];
476	
477	  heroes.forEach(h => {
478	    const tierField = gameConfig.hasLanes ? getTierField(h) : "tier";
479	    const tier = h[tierField];
480	    if (tier && validTiers.has(tier)) {
481	      groups[tier].push(h);
482	    } else {
483	      // 诊断：捕获异常梯度值
484	      console.warn("[梯度异常] 英雄:", h.name,
485	        "| 分路:", h.lane || "-",
486	        "| 梯度字段:", tierField,
487	        "| 梯度值:", tier,
488	        "| 有效字段存在:", {
489	          tier_zscore: "tier_zscore" in h ? h.tier_zscore : "缺失",
490	          tier_simple: "tier_simple" in h ? h.tier_simple : "缺失",
491	          tier: "tier" in h ? h.tier : "缺失"
492	        });
493	      unknownGroup.push(h);
494	    }
495	  });
496	
497	  // 组内按分数排序
498	  const scoreKey = getScoreField();
499	  tierOrder.forEach(t => {
500	    if (groups[t]) groups[t].sort((a, b) => b[scoreKey] - a[scoreKey]);
501	  });
502	
503	  let html = '<div class="tier-grid">';
504	  tierOrder.forEach(t => {
505	    const list = groups[t] || [];
506	    const color = colors[t] || "#8c8c8c";
507	    html += `<div class="tier-row${list.length === 0 ? " tier-row-empty" : ""}">`;
508	    html += `<div class="tier-label" style="background:${color}">${t}</div>`;
509	    html += '<div class="tier-icons">';
510	    if (list.length === 0) {
511	      html += '暂无英雄';
512	    } else {
513	      list.forEach(h => {
514	        const name = h.name;
515	        html += `<div class="tier-hero" title="${name}" onclick="showHeroDetail('${name.replace(/'/g, "\\'")}')">`;
516	        if (h.headIcon) {
517	          html += `<div class="tier-hero-img-wrap">`;
518	          html += `<img src="${h.headIcon}" alt="${name}" loading="lazy" onerror="this.style.display='none'">`;
