1062	function renderHeroDetail(name) {
1063	  const points = heroTimelineDates.map(d => {
1064	    const h = heroTimeline[d] ? heroTimeline[d][name] : null;
1065	    return h ? { date: d, ...h } : null;
1066	  }).filter(Boolean);
1067	  if (points.length === 0) {
1068	    document.getElementById('hdBody').innerHTML = '<p style="text-align:center;padding:40px;color:#8b949e">暂无历史数据</p>';
1069	    return;
1070	  }
1071	
1072	  const heroCount = Math.max(...heroTimelineDates.map(d => heroTimeline[d] ? Object.keys(heroTimeline[d]).length : 0), 0);
1073	
1074	  let gMin = { score: Infinity, winRate: Infinity, combatPower: Infinity, rank: Infinity, appearanceRank: Infinity };
1075	  let gMax = { score: -Infinity, winRate: -Infinity, combatPower: -Infinity, rank: -Infinity, appearanceRank: -Infinity };
1076	  for (const d of heroTimelineDates) {
1077	    if (!heroTimeline[d]) continue;
1078	    for (const [, h] of Object.entries(heroTimeline[d])) {
1079	      gMin.score = Math.min(gMin.score, h.score);
1080	      gMax.score = Math.max(gMax.score, h.score);
1081	      gMin.winRate = Math.min(gMin.winRate, h.winRate);
1082	      gMax.winRate = Math.max(gMax.winRate, h.winRate);
1083	      gMin.combatPower = Math.min(gMin.combatPower, h.combatPower);
1084	      gMax.combatPower = Math.max(gMax.combatPower, h.combatPower);
1085	      const invRank = heroCount - h.rank + 1;
1086	      gMin.rank = Math.min(gMin.rank, invRank);
1087	      gMax.rank = Math.max(gMax.rank, invRank);
1088	      const invAR = heroCount - h.appearanceRank + 1;
1089	      gMin.appearanceRank = Math.min(gMin.appearanceRank, invAR);
1090	      gMax.appearanceRank = Math.max(gMax.appearanceRank, invAR);
1091	    }
1092	  }
1093	
1094	  function norm(val, min, max) { return ((val - min) / (max - min || 1)) * 100; }
1095	
1096	  let html = '<div class="chart-box"><canvas id="chartHeroTimeline" style="height:360px"></canvas></div>';
1097	  html += `<table class="mini-table"><thead><tr><th>日期</th><th>梯度</th><th>排名</th><th>评分</th><th>胜率</th><th>战力</th><th>出场排名</th></tr></thead><tbody>`;
1098	  points.forEach(p => {
1099	    html += `<tr><td>${p.date}</td><td>${getTierBadge(p.tier)}</td><td>#${p.rank}</td><td>${p.score.toFixed(1)}</td><td>${(p.winRate*100).toFixed(2)}%</td><td>${p.combatPower}</td><td>#${p.appearanceRank}</td></tr>`;
1100	  });
1101	  html += '</tbody></table>';
1102	  document.getElementById('hdBody').innerHTML = html;
1103	
1104	  new Chart(document.getElementById('chartHeroTimeline'), {
1105	    type: 'line',
1106	    data: {
1107	      labels: points.map(p => p.date),
1108	      datasets: [
1109	        { label: '评分', data: points.map(p => norm(p.score, gMin.score, gMax.score)), borderColor: '#58a6ff', backgroundColor: '#58a6ff', tension: 0.2, borderWidth: 2.5, pointRadius: 5 },
1110	        { label: '胜率', data: points.map(p => norm(p.winRate, gMin.winRate, gMax.winRate)), borderColor: '#3fb950', backgroundColor: '#3fb950', tension: 0.2, borderWidth: 2.5, pointRadius: 5 },
1111	        { label: '战力', data: points.map(p => norm(p.combatPower, gMin.combatPower, gMax.combatPower)), borderColor: '#d2991d', backgroundColor: '#d2991d', tension: 0.2, borderWidth: 2.5, pointRadius: 5 },
1112	        { label: '排名', data: points.map(p => norm(heroCount - p.rank + 1, gMin.rank, gMax.rank)), borderColor: '#ff7a45', backgroundColor: '#ff7a45', tension: 0.2, borderWidth: 2.5, pointRadius: 5, borderDash: [6, 3] },
1113	        { label: '出场排名', data: points.map(p => norm(heroCount - p.appearanceRank + 1, gMin.appearanceRank, gMax.appearanceRank)), borderColor: '#bc8cff', backgroundColor: '#bc8cff', tension: 0.2, borderWidth: 2.5, pointRadius: 5, borderDash: [3, 3] },
1114	      ]
1115	    },
1116	    options: {
1117	      responsive: true, maintainAspectRatio: false,
1118	      backgroundColor: 'transparent',
1119	      plugins: {
1120	        title: { display: true, text: `${name} — 全指标趋势（归一化 0~100，越高越好）`, color: '#c9d1d9', font: { size: 14 } },
1121	        legend: { position: 'bottom', labels: { color: '#c9d1d9', usePointStyle: true, padding: 20 } },
1122	      },
1123	      scales: {
1124	        x: { ticks: { color: '#8b949e' }, grid: { color: '#21262d' } },
1125	        y: { min: 0, max: 100, ticks: { color: '#8b949e', callback: v => v.toFixed(0) }, grid: { color: '#21262d' }, title: { display: true, text: '归一化值 (0-100)', color: '#8b949e' } }
1126	      }
1127	    }
1128	  });
1129	}
